def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 1:
        return 'C' if history[0][1] == 'C' else 'D'

    my = [h[0] for h in history]
    op = [h[1] for h in history]

    op_c = op.count('C')
    op_d = n - op_c
    my_d = my.count('D')

    opp_last = op[-1]
    my_last = my[-1]

    # Current trailing run of opponent defections / cooperations
    run_d = 0
    for i in range(n - 1, -1, -1):
        if op[i] == 'D':
            run_d += 1
        else:
            break
    run_c = 0
    for i in range(n - 1, -1, -1):
        if op[i] == 'C':
            run_c += 1
        else:
            break

    remaining = 100 - n

    # Score tracking to inform endgame exploitation decisions
    my_score = 0
    op_score = 0
    for i in range(n):
        a = my[i]
        b = op[i]
        if a == 'C' and b == 'C':
            my_score += 3
            op_score += 3
        elif a == 'C' and b == 'D':
            op_score += 5
        elif a == 'D' and b == 'C':
            my_score += 5
        else:
            my_score += 1
            op_score += 1

    # ---- Opponent archetype detection ----

    # Always-cooperator: groom, then exploit at the end.
    if n >= 8 and op_d == 0:
        if remaining > 4:
            # Defect sparingly so partner keeps cooperating and we still gain.
            if n >= 12 and n % 9 == 0:
                return 'D'
            return 'C'
        return 'D'

    # Always-defector (or near): best response.
    if op_c == 0:
        return 'D'
    if n >= 10 and op_c <= 1:
        return 'D'

    # Tit-for-tat mimic: they copy our previous action.
    if n >= 6:
        mimic = 0
        for i in range(1, n):
            if op[i] == my[i - 1]:
                mimic += 1
        if mimic >= n - 2:
            # We can ride cooperation; occasionally exploit then restore.
            if remaining <= 1:
                return 'D'
            if opp_last == 'D':
                return 'C'
            if remaining > 10 and n % 11 == 0:
                return 'D'
            return 'C'

    # Grim trigger: cooperated until our first defection, then always defects.
    if my_d >= 1:
        first_d = -1
        for i in range(n):
            if my[i] == 'D':
                first_d = i
                break
        if first_d >= 0 and first_d + 1 < n:
            all_d_after = True
            for i in range(first_d + 1, n):
                if op[i] != 'D':
                    all_d_after = False
                    break
            if all_d_after:
                return 'D'

    # ---- Endgame ----
    if remaining <= 1:
        # Last round: defect if partner is likely to cooperate.
        if op_c >= op_d:
            return 'D'
        return 'D'

    if remaining <= 4:
        if op_c * 2 >= n:
            return 'D'
        if opp_last == 'D':
            return 'D'
        return 'D' if rng.random() < 0.7 else 'C'

    if remaining <= 10:
        if op_c * 3 >= n * 2:
            return 'D'
        if run_d >= 2:
            return 'D'
        if opp_last == 'C' and run_c >= 3:
            return 'C'
        if op_d * 3 > n * 2:
            return 'D'
        return 'C'

    # ---- Core play ----

    # Punish sustained defection, but attempt to break long mutual-defect wars.
    if opp_last == 'D':
        if run_d >= 4:
            # Try a conciliatory move occasionally to end the spiral.
            if rng.random() < 0.25:
                return 'C'
            return 'D'
        if run_d == 3:
            return 'C' if rng.random() < 0.2 else 'D'
        if run_d == 2:
            return 'C' if rng.random() < 0.2 else 'D'
        # Isolated defection: retaliate once, then be ready to forgive.
        if my_last == 'D':
            return 'C'
        return 'D'

    # Opponent cooperated. Preserve mutual cooperation; probe rarely.
    if my_last == 'D':
        # We defected and they still cooperated - return to cooperation.
        return 'C'

    # Both cooperating: keep it, with rare low-cost probes only when
    # we have a strong read that they are highly cooperative.
    if op_c * 10 >= n * 9:
        if remaining > 15 and n % 19 == 0 and rng.random() < 0.4:
            return 'D'
    elif op_c * 5 >= n * 4:
        if remaining > 20 and n % 23 == 0 and rng.random() < 0.3:
            return 'D'

    return 'C'
